/** Furnitorët — someone this business buys from, and where the account stands. */
export interface Supplier {
  id: string;
  owner_id: string;
  /** Emri */
  name: string;
  /** Përshkrimi */
  description: string | null;
  /** Vlera — whole Lek. */
  value: number;
  /** Pagesa — paid so far, whole Lek. */
  payment: number;
  /** Teprica — value − payment, generated by the database. */
  balance: number;
  created_at: string;
}

/**
 * Furnizimet — one product bought from a supplier. Kosto and çmimi i shitjes
 * are each recorded in Lekë and in Euro, typed in, never converted. The value
 * and difference columns are generated by the database.
 */
export interface Supply {
  id: string;
  owner_id: string;
  /** Emri i produktit */
  product_name: string;
  /** Furnitori */
  supplier_id: string | null;
  /** Data */
  supply_date: string;
  /** Sasia (copë) */
  quantity: number;
  /** Kosto për copë, Lekë */
  cost_all: number;
  /** Kosto për copë, Euro */
  cost_eur: number;
  /** Çmimi i shitjes për copë, Lekë */
  sale_price_all: number;
  /** Çmimi i shitjes për copë, Euro */
  sale_price_eur: number;
  /** Vlera në Lekë — cost_all × sasia */
  value_all: number;
  /** Vlera në Euro — cost_eur × sasia */
  value_eur: number;
  /** Diferenca në Lekë — (sale_price_all − cost_all) × sasia */
  difference_all: number;
  /** Diferenca në Euro — (sale_price_eur − cost_eur) × sasia */
  difference_eur: number;
  created_at: string;
}

export interface SuppliersManagerProps {
  suppliers: Supplier[];
}

export interface SupplierDraft {
  id: string | null;
  name: string;
  description: string;
  value: number;
  payment: number;
}

export interface SuppliesManagerProps {
  supplies: Supply[];
  suppliers: Pick<Supplier, 'id' | 'name' | 'description'>[];
}

export interface SupplyDraft {
  id: string | null;
  product_name: string;
  supplier_id: string;
  supply_date: string;
  quantity: number;
  cost_all: number;
  cost_eur: number;
  sale_price_all: number;
  sale_price_eur: number;
}

export type SupplyPrices = Pick<
  SupplyDraft,
  'quantity' | 'cost_all' | 'cost_eur' | 'sale_price_all' | 'sale_price_eur'
>;
